package com.autoops.auth.service;
import com.autoops.auth.dto.AuthDtos;import com.autoops.user.repository.UserRepository;import org.springframework.security.authentication.*;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Service;
@Service public class AuthService{private final AuthenticationManager auth;private final UserRepository users;private final JwtService jwt;public AuthService(AuthenticationManager a,UserRepository u,JwtService j){auth=a;users=u;jwt=j;}public AuthDtos.AuthResponse login(AuthDtos.LoginRequest r){Authentication x=auth.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password()));var u=users.findByUsername(x.getName()).orElseThrow();return new AuthDtos.AuthResponse(jwt.create(u.getId(),u.getRole().name()),900);}}
